var appMount = null;
var windowOpen = false;
function buildSettingsWindow(mount) {
  appMount = mount;
  mount.root.id = "prompt-slot-modal-overlay";
  mount.root.classList.add("megumin-suite-app");
  mount.root.innerHTML = WINDOW_HTML;
  watchIcons(mount.root);
  closeSettingsWindow();
  return mount.root;
}
function openSettingsWindow() {
  if (!appMount)
    return;
  windowOpen = true;
  appMount.setVisible(true);
  appMount.root.classList.add("megumin-open");
}
function closeSettingsWindow() {
  if (!appMount)
    return;
  windowOpen = false;
  appMount.root.classList.remove("megumin-open");
  appMount.setVisible(false);
}
function isSettingsWindowOpen() {
  return windowOpen;
}
function buildLauncher(widget, onOpen) {
  widget.root.classList.add("meg-float");
  widget.root.innerHTML = `<button id="prompt-slot-fixed-btn" class="meg-float-btn" type="button" title="Megumin Suite" aria-label="Megumin Suite">` + LAUNCHER_ICON_SVG + `</button>`;
  bindLauncher(widget.root.querySelector("button"), onOpen);
}
function bindLauncher(button, onOpen) {
  if (!button)
    return;
  const THRESHOLD_PX = 6;
  let start = null;
  let dragged = false;
  button.addEventListener("pointerdown", (event) => {
    start = { x: event.clientX, y: event.clientY };
    dragged = false;
  });
  button.addEventListener("pointerup", (event) => {
    if (!start)
      return;
    if (Math.hypot(event.clientX - start.x, event.clientY - start.y) > THRESHOLD_PX)
      dragged = true;
    start = null;
  });
  button.addEventListener("pointercancel", () => {
    start = null;
    dragged = true;
  });
  button.addEventListener("click", (event) => {
    if (dragged) {
      dragged = false;
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    onOpen();
  }, true);
}

