function meguminCotForMode(modeId, lang = "english") {
  if (!modeId)
    return null;
  let prefix = null;
  if (modeId.includes("v6"))
    prefix = "cot-v6";
  else if (modeId === "v7.5")
    prefix = "cot-v7.5";
  else if (modeId.includes("v7"))
    prefix = "cot-v7";
  else if (modeId.includes("v8"))
    prefix = "cot-v8";
  else if (modeId === "v11-voice" || modeId === "v11-deepseek")
    prefix = "cot-v11-voice";
  else if (modeId === "v11-writers-room")
    prefix = "cot-v11-wr";
  else if (modeId.includes("v11"))
    prefix = "cot-v11";
  else if (modeId.includes("v10-shura"))
    prefix = "cot-v10-shura";
  else if (modeId.includes("v10"))
    prefix = "cot-v10-ukiyo";
  else if (modeId.includes("v9"))
    prefix = "cot-v9";
  if (!prefix)
    return null;
  const englishOnly = prefix.startsWith("cot-v11") || prefix.startsWith("cot-v10") || prefix.includes("v7") || prefix.includes("v8");
  const id = englishOnly ? `${prefix}-english` : `${prefix}-${lang}`;
  return models.find((m) => m.id === id) ? id : null;
}
function meguminCotEntryForMode(modeId, lang = "english") {
  const id = meguminCotForMode(modeId, lang);
  return id ? models.find((m) => m.id === id) || null : null;
}

