var isV7Engine = (m) => !!m && (String(m.id || "").startsWith("v7") || m.isV7 === true);
var isV8Engine = (m) => !!m && (String(m.id || "").startsWith("v8") || m.isV8 === true);
var isV9Engine = (m) => !!m && (String(m.id || "").startsWith("v9") || m.isV9 === true);
var isV10Engine = (m) => !!m && (String(m.id || "").startsWith("v10") || m.isV10 === true);
var isV11Engine = (m) => !!m && (String(m.id || "").startsWith("v11") || m.isV11 === true);
var isCoWriterEngine = (m) => !!m && (m.isCoWriter === true || String(m.id || "").endsWith("-cw"));
var isModernEngine = (m) => isV8Engine(m) || isV9Engine(m) || isV10Engine(m) || isV11Engine(m);
var engineLocksStyle = (m) => isV7Engine(m) || isModernEngine(m);
var engineUsesRenderLimits = (m) => isV9Engine(m) && !isV10Engine(m);
var engineKeepsNotebook = (m) => !!m && m.notebook === true;
function lockedStyleIdFor(m) {
  if (!m)
    return null;
  if (m.id === "v7-core")
    return "dir_v7_core";
  if (m.id === "v7-gentle")
    return "dir_v7_gentle";
  if (m.id === "v7.5")
    return "dir_v7.5";
  if (isV8Engine(m))
    return "dir_v8";
  if (isV11Engine(m))
    return "dir_v11";
  if (String(m.id || "").startsWith("v10-shura"))
    return "dir_v10_shura";
  if (isV10Engine(m))
    return "dir_v10_ukiyo";
  if (isV9Engine(m))
    return "dir_v9";
  if (isV7Engine(m))
    return "dir_v7";
  return null;
}
var STYLE_FAMILY = { dir_v11: ["dir_v11", "dir_v11_inside"] };
function styleAfterPicking(m, activeStyleId, isBuiltIn) {
  const locked = lockedStyleIdFor(m);
  if (!locked)
    return null;
  if (activeStyleId && !isBuiltIn)
    return null;
  return (STYLE_FAMILY[locked] || [locked]).includes(activeStyleId) ? null : locked;
}

