// src/prompts/defaults.js
var DEFAULT_PROMPTS = {
  storyPlan: storyPlanPrompts,
  banList: banListPrompts,
  imageGen: imageGenPrompts,
  memoryCore: memoryCorePrompts,
  npcBank: npcBankPrompts
};
var MEGUMIN_PROMPT_MODULES = ["storyPlan", "imageGen", "memoryCore", "npcBank"];

// src/prompts/storage.js
function meguminDiffPrompts(prompts, moduleName) {
  const base = DEFAULT_PROMPTS[moduleName];
  if (!prompts || typeof prompts !== "object" || !base)
    return prompts ?? null;
  const diff = {};
  for (const [k, v] of Object.entries(prompts)) {
    if (!(k in base) || JSON.stringify(v) !== JSON.stringify(base[k]))
      diff[k] = v;
  }
  return Object.keys(diff).length > 0 ? diff : null;
}
function meguminFillPrompts(prompts, moduleName) {
  const base = DEFAULT_PROMPTS[moduleName];
  if (!prompts || typeof prompts !== "object" || !base)
    return prompts;
  for (const [k, v] of Object.entries(base)) {
    if (prompts[k] === undefined)
      prompts[k] = JSON.parse(JSON.stringify(v));
  }
  return prompts;
}
function meguminSparsifyProfilePrompts(prof) {
  if (!prof || typeof prof !== "object")
    return prof;
  for (const mod of MEGUMIN_PROMPT_MODULES) {
    if (prof[mod] && prof[mod].customPrompts) {
      prof[mod].customPrompts = meguminDiffPrompts(prof[mod].customPrompts, mod);
    }
  }
  if (prof.banListCustomPrompts) {
    prof.banListCustomPrompts = meguminDiffPrompts(prof.banListCustomPrompts, "banList");
  }
  return prof;
}
function meguminRehydrateProfilePrompts(prof) {
  if (!prof || typeof prof !== "object")
    return prof;
  for (const mod of MEGUMIN_PROMPT_MODULES) {
    if (prof[mod] && prof[mod].customPrompts) {
      meguminFillPrompts(prof[mod].customPrompts, mod);
    }
  }
  if (prof.banListCustomPrompts) {
    meguminFillPrompts(prof.banListCustomPrompts, "banList");
  }
  return prof;
}
function meguminPromptBytes(prof) {
  let n = 0;
  for (const mod of MEGUMIN_PROMPT_MODULES) {
    if (prof[mod] && prof[mod].customPrompts)
      n += JSON.stringify(prof[mod].customPrompts).length;
  }
  if (prof.banListCustomPrompts)
    n += JSON.stringify(prof.banListCustomPrompts).length;
  return n;
}
function meguminCompactStoredPrompts() {
  const profiles = extension_settings[extensionName] && extension_settings[extensionName].profiles;
  if (!profiles)
    return;
  let before = 0, after = 0, touched = 0;
  for (const prof of Object.values(profiles)) {
    if (!prof || typeof prof !== "object")
      continue;
    const was = meguminPromptBytes(prof);
    if (was === 0)
      continue;
    meguminSparsifyProfilePrompts(prof);
    const now = meguminPromptBytes(prof);
    before += was;
    after += now;
    if (now !== was)
      touched++;
  }
  if (touched > 0) {
    saveSettingsDebounced();
    console.log(`[Megumin Suite] Compacted duplicated prompt text across ${touched} profiles: ` + `${(before / 1024).toFixed(0)}KB -> ${(after / 1024).toFixed(0)}KB in settings.json.`);
  }
}

