// src/engine/chomusukeNotice.js
var CHOMUSUKE_JOB_NAMES = {
  worldState: "World State",
  blocks: "Blocks",
  notebook: "The Notebook",
  imageGen: "the image",
  memory: "the memory summary",
  storyPlan: "the Story Director",
  npc: "the NPC Bank",
  banList: "Banned Phrases",
  styleGen: "the writing style",
  test: "the test"
};
var HAS_READ_AGAIN = new Set(["worldState", "blocks", "notebook"]);
var nameOf = (job) => CHOMUSUKE_JOB_NAMES[job] || job;
function joinJobNames(jobs) {
  const names = jobs.map(nameOf);
  if (names.length <= 1)
    return names[0] || "";
  return `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`;
}
function answerKind(raw) {
  const text = String(raw ?? "").replace(/<think\b[^>]*>[\s\S]*?(<\/think\s*>|$)/gi, "").trim();
  return text ? "format" : "empty";
}
function chomusukeProblemText(kind, jobs, { error, switchedBack = false } = {}) {
  const what = joinJobNames(jobs);
  const readAgain = jobs.some((j) => HAS_READ_AGAIN.has(j));
  if (kind === "failed") {
    const why = String(error?.message || error || "").trim().slice(0, 200);
    return `Chomusuke couldn't get an answer for ${what}${why ? `: ${why}` : ""}.` + (readAgain ? " Use Read again on the card once the connection works." : "") + (switchedBack ? " Your story connection is back." : "");
  }
  if (kind === "empty") {
    return `Chomusuke's model sent back nothing for ${what}. A censored model can refuse an NSFW story without a word: try a less censored one in the Chomusuke tab, or check its connection there` + (readAgain ? ", then use Read again on the card." : ".");
  }
  return `Chomusuke answered, but not in a format it could use for ${what}, so nothing changed. ` + (readAgain ? "Use Read again on the card, or pick a stronger model for Chomusuke." : "Pick a stronger model for Chomusuke if this keeps happening.");
}
function warnChomusuke(kind, jobs, opts) {
  if (!jobs.length || typeof toastr === "undefined")
    return;
  const text = chomusukeProblemText(kind, jobs, opts);
  if (kind === "failed")
    toastr.error(text, "Chomusuke", { timeOut: 8000 });
  else
    toastr.warning(text, "Chomusuke", { timeOut: 7000 });
}

// src/engine/workerRequest.js
function workerRoute({ profileId, currentId, hasService, fallback }) {
  if (!profileId || profileId === currentId)
    return "current";
  if (!hasService || fallback)
    return "switch";
  return "profile";
}
var MARKER2 = /^___PS_[A-Z_]+___$/;
function isJobMarker(text) {
  return MARKER2.test(String(text || "").trim());
}
function plainMessages(text) {
  const t = String(text || "").trim();
  return t ? [{ role: "user", content: t }] : [];
}
function replyLength(presetLength, storyLength) {
  for (const n of [presetLength, storyLength]) {
    const v = Math.floor(Number(n));
    if (Number.isFinite(v) && v > 0)
      return v;
  }
  return 1024;
}
function answerOf(res) {
  if (typeof res === "string")
    return res;
  if (res && typeof res.content === "string")
    return res.content;
  return "";
}
function requestError(e) {
  let err = e;
  for (let i = 0;i < 4 && err && err.cause; i++)
    err = err.cause;
  const msg = String(err && err.message || err || "").trim();
  return msg || String(e && e.message || e || "").trim();
}
function isChatProfile(p) {
  return Boolean(p) && p.mode !== "tc";
}
var READS_THE_REPLY = new Set(["worldState", "blocks", "notebook"]);
function storyWaitsFor(jobs) {
  return (jobs || []).some((j) => READS_THE_REPLY.has(j));
}
