  const offscreen = Object.values(state.cast || {}).filter((c) => !c.present && c.offscreen);
  if (offscreen.length) {
    out.push("---", "**\uD83D\uDCE1 Off-Screen:**");
    for (const c of offscreen)
      out.push(`* ${c.name} — ${c.offscreen}`);
    out.push("");
  }
  const tail = [];
  if ((state.threads || []).length) {
    tail.push("**\uD83D\uDD25 Unresolved Threads:**");
    for (const t of state.threads)
      tail.push(`* ${t}`);
  }
  if (!opts.noSecret && (state.seeds || []).length)
    tail.push(`**\uD83C\uDF31 Planted Seeds:** ${state.seeds.join("; ")}`);
  if ((state.timers || []).length)
    tail.push(`**⏳ Consequence Timers:** ${state.timers.join("; ")}`);
  if (state.arcPhase)
    tail.push(`**\uD83C\uDFAF Arc Phase:** ${state.arcPhase}`);
  if (state.scenePhase)
    tail.push(`**\uD83C\uDFAC Scene Phase:** ${state.scenePhase}`);
  if (tail.length)
    out.push("---", ...tail);
  return out.join(`
`).replace(/\n{3,}/g, `

`).trim();
