var SCENE_NAME = { time: "Time", location: "Loc", weather: "Wx" };
var PHASE_NAME = { arcPhase: "Arc", scenePhase: "Scene" };
var LIST_NAME = { threads: "Thread", seeds: "Seed", timers: "Timer" };
function describeWorldChange(ch, pcLabel = "{{user}}") {
  const who = (w) => w === "{{pc}}" ? pcLabel : w;
  switch (ch && ch.type) {
    case "scene":
      return `${SCENE_NAME[ch.key] || ch.key}: ${ch.value}`;
    case "phase":
      return `${PHASE_NAME[ch.key] || ch.key}: ${ch.value}`;
    case "field":
      return `${who(ch.who)} · ${fieldLabel(ch.field)}: ${ch.value || "(cleared)"}`;
    case "enter":
      return `${who(ch.who)} entered`;
    case "leave":
      return `${who(ch.who)} left${ch.where ? `: ${ch.where}` : ""}`;
    case "offscreen":
      return `${ch.who ? who(ch.who) + " " : ""}off-screen: ${ch.value}`;
    case "offscreenRemove":
      return `${who(ch.who)} off-screen line removed`;
    case "forget":
      return `${who(ch.who)} removed`;
    case "merge":
      return `${who(ch.who)} is ${who(ch.into)}`;
    case "pcname":
      return `Player character: ${ch.name}`;
    case "list": {
      const n = LIST_NAME[ch.list] || ch.list;
      return ch.op === "remove" ? `${n} −: ${ch.value}` : ch.op === "add" ? `${n} +: ${ch.value}` : `${n}: ${ch.value}`;
    }
    default:
      return "";
  }
}
function renderWorldClerkTask(mode, { noSecret = false } = {}) {
  const ins = renderWorldInstructions(mode, { noSecret });
  const reword = (t) => t.replace(/before your reply/g, "before the latest exchange").replace(/what your reply changed/g, "what the latest exchange changed").replace(/at the END of your reply/g, "at the END of the latest exchange").replace(/in your prose/g, "in the prose").replace(/your reply/g, "the latest exchange");
  return { rules: reword(ins.rules), template: ins.template, tag: mode === "bootstrap" ? "World_State" : "World_Update" };
}
function renderClerkNotes(notes) {
  return notes ? notes.replace(/<!--[\s\S]*?-->/, "<!-- Where the story stood before the latest exchange. -->") : `<Current_World_State>
(Nothing has been noted about this story yet.)
</Current_World_State>`;
}
function renderWorldExtractPrompt({ notes, exchange, mode, noSecret = false, sheets = "" }) {
  const task = renderWorldClerkTask(mode, { noSecret });
  const s = String(sheets || "").trim();
  const system = "You are a continuity clerk for an ongoing roleplay. You read the latest exchange and note what it changed: " + "the physical scene, who is present and how they look, and the story's slow deep currents. " + (s ? "The character sheets tell you who the characters and {{user}} are; use them to understand the people. " + "You never write story, never explain, and never add facts that neither the exchange nor the sheets give you." : "You never write story, never explain, and never add facts the exchange does not state or clearly show.");
  const user = [
    ...s ? [`<Character_Sheets>
${s}
</Character_Sheets>`, ""] : [],
    renderClerkNotes(notes),
    "",
    "<Latest_Exchange>",
    String(exchange || "").trim(),
    "</Latest_Exchange>",
    "",
    task.rules,
    "",
    `Output ONLY the <${task.tag}> block, nothing before or after it, in this shape:`,
    task.template
  ].join(`
`);
  return { system, user, prefill: `<${task.tag}>
`, tag: task.tag };
}

