// src/features/imagegen/comfyProgress.js
function makeComfyClientId() {
  try {
    if (crypto && typeof crypto.randomUUID === "function")
      return crypto.randomUUID();
  } catch (e) {}
  return "megumin-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 10);
}
function openComfyProgressSocket(comfyUrl, clientId, { onProgress, onNode } = {}) {
  let ws = null;
  let closed = false;
  try {
    const base = String(comfyUrl || "").trim().replace(/\/+$/, "");
    const wsUrl = base.replace(/^https:/i, "wss:").replace(/^http:/i, "ws:") + "/ws?clientId=" + encodeURIComponent(clientId);
    ws = new WebSocket(wsUrl);
    ws.onmessage = (ev) => {
      if (closed)
        return;
      if (typeof ev.data !== "string")
        return;
      let msg;
      try {
        msg = JSON.parse(ev.data);
      } catch (e) {
        return;
      }
      if (!msg || !msg.type)
        return;
      if (msg.type === "progress" && msg.data && typeof msg.data.max === "number" && msg.data.max > 0) {
        if (typeof onProgress === "function")
          onProgress(msg.data.value || 0, msg.data.max);
      } else if (msg.type === "executing" && msg.data) {
        if (typeof onNode === "function")
          onNode(msg.data.node ?? null);
      }
    };
    ws.onerror = () => {};
  } catch (e) {
    console.debug("[Megumin Suite] ComfyUI progress socket unavailable; using the indeterminate bar.", e);
    ws = null;
  }
  return {
    close() {
      closed = true;
      try {
        if (ws)
          ws.close();
      } catch (e) {}
      ws = null;
    }
  };
}

// src/features/imagegen/comfyUrl.js
function comfyBase(url) {
  return String(url || "").trim().replace(/\/+$/, "");
}

// src/features/imagegen/comfy.js
var LIST_TIMEOUT_MS = 1e4;
var PING_TIMEOUT_MS = 6000;
var timeout = (ms) => typeof AbortSignal !== "undefined" && AbortSignal.timeout ? AbortSignal.timeout(ms) : undefined;
async function igFetchComfyLists() {
  const s = localProfile.imageGen;
  const url = comfyBase(s.comfyUrl);
  try {
    const mRes = await comfyFetch("/api/sd/comfy/models", { method: "POST", headers: getRequestHeaders(), body: JSON.stringify({ url }), signal: timeout(LIST_TIMEOUT_MS) });
    if (mRes.ok) {
      const models = await mRes.json();
      const sel = $("#ig_model");
      sel.empty().append('<option value="">-- Select Model --</option>');
      models.forEach((m) => {
        let v = m.value || m;
        let t = m.text || v;
        sel.append(`<option value="${v}">${t}</option>`);
      });
      if (s.selectedModel)
        sel.val(s.selectedModel);
    }
    const sRes = await comfyFetch("/api/sd/comfy/samplers", { method: "POST", headers: getRequestHeaders(), body: JSON.stringify({ url }), signal: timeout(LIST_TIMEOUT_MS) });
    if (sRes.ok) {
      const samplers = await sRes.json();
      const sel = $("#ig_sampler");
      sel.empty();
      samplers.forEach((sa) => sel.append(`<option value="${sa}">${sa}</option>`));
      if (s.selectedSampler)
        sel.val(s.selectedSampler);
    }
    const lRes = await comfyFetch(`${url}/object_info/LoraLoader`, { signal: timeout(LIST_TIMEOUT_MS) });
    if (lRes.ok) {
      const json = await lRes.json();
      const files = json["LoraLoader"].input.required.lora_name[0];
      for (let i = 1;i <= 4; i++) {
        const sel = $(`#ig_lora_${i}`);
        const val = i === 1 ? s.selectedLora : s[`selectedLora${i}`];
        sel.empty().append('<option value="">-- No LoRA --</option>');
        files.forEach((f) => sel.append(`<option value="${f}">${f}</option>`));
        if (val)
          sel.val(val);
      }
    }
  } catch (e) {
    console.warn(`[Megumin-Suite] ComfyLists failed`, e);
  }
}
function imageSource() {
  return localProfile?.imageGen?.imageSource === "lumi" ? "lumi" : "comfy";
}
var quickGenAction = null;
function setQuickGenAction(handle) {
  quickGenAction = handle;
  toggleQuickGenButton();
}
function toggleQuickGenButton() {
  const s = localProfile?.imageGen;
  const on = Boolean(s && s.enabled);
  try {
    quickGenAction && quickGenAction.setEnabled(on);
  } catch (e) {}
}
var conn2 = { url: null, ok: null, pending: null };
function igKnownConnection() {
  if (imageSource() === "lumi")
    return lumiKnownConnection();
  const url = localProfile?.imageGen?.comfyUrl;
  return conn2.url === url ? conn2.ok : null;
}
function igCheckConnection({ force = false } = {}) {
  if (imageSource() === "lumi")
    return lumiCheckConnection({ force });
  const url = localProfile?.imageGen?.comfyUrl;
  if (!url)
    return Promise.resolve(false);
  if (!force && conn2.url === url) {
    if (conn2.pending)
      return conn2.pending;
    if (conn2.ok !== null)
      return Promise.resolve(conn2.ok);
  }
  conn2.url = url;
  conn2.ok = null;
  const job = (async () => {
    try {
      const res = await comfyFetch("/api/sd/comfy/ping", { method: "POST", headers: getRequestHeaders(), body: JSON.stringify({ url }), signal: timeout(PING_TIMEOUT_MS) });
      return res.ok;
    } catch (e) {
      return false;
    }
  })().then((ok) => {
    if (conn2.url === url && conn2.pending === job) {
      conn2.ok = ok;
      conn2.pending = null;
    }
    return ok;
  });
  conn2.pending = job;
  return job;
}
async function igTestConnection() {
  if (imageSource() === "lumi")
    return lumiTestConnection();
  const ok = await igCheckConnection({ force: true });
  if (ok) {
    toastr.success("ComfyUI is connected.", "Megumin Suite");
    await igFetchComfyLists();
  } else
    toastr.error("ComfyUI didn't answer at this address. It is reached from the Lumiverse server, so the address must work from that machine (127.0.0.1 is the server itself). Also check that Megumin Suite has the CORS proxy permission.", "Megumin Suite");
  return ok;
}
async function igPopulateWorkflows() {
  const sel = $("#ig_workflow_list");
  sel.empty();
  try {
    const res = await comfyFetch("/api/sd/comfy/workflows", { method: "POST", headers: getRequestHeaders(), body: JSON.stringify({ url: localProfile.imageGen.comfyUrl }), signal: timeout(LIST_TIMEOUT_MS) });
    if (res.ok) {
      const wfs = await res.json();
      wfs.forEach((w) => sel.append(`<option value="${w}">${w}</option>`));
      if (localProfile.imageGen.currentWorkflowName && wfs.includes(localProfile.imageGen.currentWorkflowName)) {
        sel.val(localProfile.imageGen.currentWorkflowName);
      } else if (wfs.length > 0) {
        sel.val(wfs[0]);
        localProfile.imageGen.currentWorkflowName = wfs[0];
        saveProfileToMemory();
      }
    }
  } catch (e) {
    sel.append("<option disabled>Failed to load</option>");
  }
}
async function igNewWorkflowClick() {
  let name = await new Popup("New workflow file name (e.g. 'my_flux.json'):", POPUP_TYPE.INPUT, "").show();
  if (!name)
    return;
  if (!name.toLowerCase().endsWith(".json"))
    name += ".json";
  try {
    const res = await comfyFetch("/api/sd/comfy/save-workflow", { method: "POST", headers: getRequestHeaders(), body: JSON.stringify({ file_name: name, workflow: "{}" }) });
    if (!res.ok)
      throw new Error(await res.text());
    toastr.success("Workflow created!");
    await igPopulateWorkflows();
    $("#ig_workflow_list").val(name).trigger("change");
    setTimeout(igOpenWorkflowEditorClick, 500);
  } catch (e) {
    toastr.error(e.message);
  }
}
async function igDeleteWorkflowClick() {
  const name = localProfile.imageGen.currentWorkflowName;
  if (!name)
    return;
  if (!confirm(`Delete ${name}?`))
    return;
  try {
    const res = await comfyFetch("/api/sd/comfy/delete-workflow", { method: "POST", headers: getRequestHeaders(), body: JSON.stringify({ file_name: name }) });
    if (!res.ok)
      throw new Error(await res.text());
    toastr.success("Deleted.");
    await igPopulateWorkflows();
  } catch (e) {
    toastr.error(e.message);
  }
}
async function igOpenWorkflowEditorClick() {
  const name = localProfile.imageGen.currentWorkflowName;
  if (!name)
    return toastr.warning("No workflow selected");
  let loadedContent = "{}";
  try {
    const res = await comfyFetch("/api/sd/comfy/workflow", { method: "POST", headers: getRequestHeaders(), body: JSON.stringify({ file_name: name }) });
    if (res.ok) {
      const rawBody = await res.json();
      let jsonObj = rawBody;
      if (typeof rawBody === "string") {
        try {
          jsonObj = JSON.parse(rawBody);
        } catch (e) {}
      }
      loadedContent = JSON.stringify(jsonObj, null, 4);
    }
  } catch (e) {
    toastr.error("Failed to load file. Starting empty.");
  }
  let currentJsonText = loadedContent;
  const $container = $(`
        <div style="display: flex; flex-direction: column; width: 100%; gap: 10px; font-family: 'Inter', sans-serif; color: var(--text-main);">
            <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--border-color); padding-bottom:10px;">
                <h3 style="margin:0; color: var(--gold);">${name}</h3>
                <div style="display:flex; gap:8px;">
                    <button class="ps-modern-btn secondary wf-format" title="Beautify JSON"><i class="fa-solid fa-align-left"></i> Format</button>
                    <button class="ps-modern-btn secondary wf-import" title="Upload .json file"><i class="fa-solid fa-upload"></i> Import</button>
                    <button class="ps-modern-btn secondary wf-export" title="Download .json file"><i class="fa-solid fa-download"></i> Export</button>
                    <input type="file" class="wf-file-input" accept=".json" style="display:none;" />
                </div>
            </div>
            <div style="display: flex; gap: 15px;">
                <textarea class="ps-modern-input wf-textarea" spellcheck="false" style="flex: 1; min-height: 500px; font-family: 'Consolas', 'Monaco', monospace; white-space: pre; resize: none; font-size: 13px; line-height: 1.4; background: #000;"></textarea>
                <div style="width: 250px; flex-shrink: 0; display: flex; flex-direction: column; border-left: 1px solid var(--border-color); padding-left: 10px; max-height: 500px;">
                    <h4 style="margin: 0 0 10px 0; color: var(--text-muted);">Placeholders</h4>
                    <div class="wf-list" style="overflow-y: auto; flex: 1; padding-right: 5px;"></div>
                </div>
            </div>
        </div>
    `);
  const $textarea = $container.find(".wf-textarea");
  const $list = $container.find(".wf-list");
  const $fileInput = $container.find(".wf-file-input");
  $textarea.val(currentJsonText);
  KAZUMA_PLACEHOLDERS.forEach((item) => {
    const $itemDiv = $("<div></div>").css({ padding: "8px", "margin-bottom": "6px", background: "rgba(255,255,255,0.05)", "border-radius": "6px", border: "1px solid transparent", transition: "0.2s" });
    $itemDiv.append($("<span></span>").text(item.key).css({ "font-weight": "bold", color: "var(--gold)", "font-family": "monospace" })).append($("<div></div>").text(item.desc).css({ "font-size": "0.7rem", color: "var(--text-muted)", "margin-top": "4px" }));
    $list.append($itemDiv);
  });
  const updateState = () => {
    currentJsonText = $textarea.val();
    $list.children().each(function() {
      const cleanKey = $(this).find("span").first().text().replace(/"/g, "");
      if (currentJsonText.includes(cleanKey))
        $(this).css({ "border-color": "#10b981", background: "rgba(16, 185, 129, 0.1)" });
      else
        $(this).css({ "border-color": "transparent", background: "rgba(255,255,255,0.05)" });
    });
  };
  $textarea.on("input", updateState);
  setTimeout(updateState, 100);
  $container.find(".wf-format").on("click", () => {
    try {
      $textarea.val(JSON.stringify(JSON.parse($textarea.val()), null, 4));
      updateState();
      toastr.success("Formatted");
    } catch (e) {
      toastr.warning("Invalid JSON");
    }
  });
  $container.find(".wf-import").on("click", () => $fileInput.click());
  $fileInput.on("change", (e) => {
    if (!e.target.files[0])
      return;
    const r = new FileReader;
    r.onload = (ev) => {
      $textarea.val(ev.target.result);
      updateState();
      toastr.success("Imported");
    };
    r.readAsText(e.target.files[0]);
    $fileInput.val("");
  });
  $container.find(".wf-export").on("click", () => {
    try {
      JSON.parse(currentJsonText);
      const a = document.createElement("a");
      a.href = URL.createObjectURL(new Blob([currentJsonText], { type: "application/json" }));
      a.download = name;
      a.click();
    } catch (e) {
      toastr.warning("Invalid content");
    }
  });
  const popup = new Popup($container, POPUP_TYPE.CONFIRM, "", { okButton: "Save Changes", cancelButton: "Cancel", wide: true, large: true, onClosing: () => {
    try {
      JSON.parse(currentJsonText);
      return true;
    } catch (e) {
      toastr.error("Invalid JSON.");
      return false;
    }
  } });
  if (await popup.show()) {
    try {
      const res = await comfyFetch("/api/sd/comfy/save-workflow", { method: "POST", headers: getRequestHeaders(), body: JSON.stringify({ file_name: name, workflow: JSON.stringify(JSON.parse(currentJsonText)) }) });
      if (!res.ok)
        throw new Error(await res.text());
      toastr.success("Workflow Saved!");
    } catch (e) {
      toastr.error("Save Failed.");
    }
  }
}
function addKazumaRetryButtons(msgIndex) {
  const context = getContext();
  const message = context.chat[msgIndex];
  const ctx = getHostContext();
  if (!message || !message.id || !ctx || !ctx.dom)
    return;
  const messageNode = ctx.dom.findMessageElement(message.id);
  if (!messageNode)
    return;
  const images = messageNode.querySelectorAll('img[alt="KazumaInline"]');
  images.forEach((img) => {
    const holder = img.parentElement;
    if (!holder || holder.querySelector(".kazuma-regen-btn"))
      return;
    const wrapperId = img.getAttribute("data-kazumaid") || "";
    let prompt2 = (img.getAttribute("title") || "").replace(/&quot;/g, '"').replace(/&#39;/g, "'");
    if (!prompt2 && wrapperId && message.mes) {
      const mesMatch = message.mes.match(new RegExp(`<img[^>]*?title="([^"]*)"[^>]*?data-kazumaid="${wrapperId}"`));
      if (mesMatch)
        prompt2 = mesMatch[1].replace(/&quot;/g, '"').replace(/&#39;/g, "'");
    }
    if (!prompt2 || !wrapperId)
      return;
    holder.style.position = "relative";
    const btn = document.createElement("div");
    btn.className = "kazuma-regen-btn";
    btn.title = "Regenerate this image";
    const canHover = !window.matchMedia || window.matchMedia("(hover: hover)").matches;
    const rest = canHover ? "0" : "0.85";
    btn.style.cssText = `position:absolute; top:8px; right:8px; cursor:pointer; background:rgba(0,0,0,0.65); color:#ffcc00; border-radius:6px; padding:5px 8px; font-size:14px; z-index:10; border:1px solid rgba(255,204,0,0.5); opacity:${rest}; transition:opacity 0.2s ease; line-height:1;`;
    btn.innerHTML = '<i class="fa-solid fa-arrows-rotate"></i>';
    holder.addEventListener("mouseenter", () => {
      btn.style.opacity = "1";
    });
    holder.addEventListener("mouseleave", () => {
      btn.style.opacity = rest;
    });
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      e.preventDefault();
      kazumaRegenerate(wrapperId, prompt2);
    });
    holder.appendChild(btn);
  });
}
