    const msg = (getContext().chat || []).find((m) => typeof m.mes === "string" && m.mes.includes(wrapperId));
    const m = msg && msg.mes.match(new RegExp(`<img[^>]*?title="([^"]*)"[^>]*?data-kazumaid="${wrapperId}"`));
