// src/features/imagegen/v2/waitFor.js
async function waitUnlessStuck(work, { limitMs = 60000, tickMs = 1000, isPaused = () => false } = {}) {
  let finished = false;
  const done = Promise.resolve(work).then(() => {
    finished = true;
  }, () => {
    finished = true;
  });
  let waited = 0;
  while (!finished) {
    let timer = null;
    await Promise.race([done, new Promise((r) => {
      timer = setTimeout(r, tickMs);
    })]);
    clearTimeout(timer);
    if (finished)
      break;
    if (!isPaused())
      waited += tickMs;
    if (waited >= limitMs)
      return "gave-up";
  }
  return "done";
}

