    if (!chat.length)
      return "";
    const res = await checkWorldInfo(chat, Number(ctx.maxContext) || 8192, true);
    const depth = (res.WIDepthEntries || []).flatMap((d) => d.entries || []);
    const parts = [res.worldInfoBefore, res.worldInfoAfter, ...res.ANBeforeEntries || [], ...res.ANAfterEntries || [], ...depth].map((t) => String(t || "").trim()).filter(Boolean);
