// src/features/imagegen/slot.js
var BLOCK_START = /<Blocks\b|<World_State\b|<World_Update\b|<details\b|<Story_Tracker\b|<NPC_Inner_Chatter\b|<New_NPC\b|<NPC_Update\b/i;
function findImageSlot(mes, placement = "end", rand = Math.random) {
  const text = String(mes || "");
  const thinkEnd = (() => {
    const i = text.toLowerCase().lastIndexOf("</think>");
    return i >= 0 ? i + "</think>".length : 0;
  })();
  const rest = text.slice(thinkEnd);
  const b = rest.search(BLOCK_START);
  let proseEnd = b >= 0 ? thinkEnd + b : text.length;
  while (proseEnd > thinkEnd && /\s/.test(text[proseEnd - 1]))
    proseEnd--;
  if (placement !== "random")
    return proseEnd;
  const breaks = [];
  const re = /\n\s*\n/g;
  const prose = text.slice(thinkEnd, proseEnd);
  let m;
  while ((m = re.exec(prose)) !== null) {
    const at = thinkEnd + m.index;
    if (prose.slice(0, m.index).trim())
      breaks.push(at);
  }
  breaks.push(proseEnd);
  return breaks[Math.min(breaks.length - 1, Math.floor(rand() * breaks.length))];
}
function insertAtSlot(mes, html, placement = "end", rand = Math.random) {
  const text = String(mes || "");
  const at = findImageSlot(text, placement, rand);
  const before = text.slice(0, at).replace(/\s+$/, "");
  const after = text.slice(at).replace(/^\s+/, "");
  return [before, html, after].filter(Boolean).join(`

`);
}

