// src/core/sharedFragments.js
function getSharedFragments() {
  const store = extension_settings[extensionName];
  if (!store)
    return {};
  if (!store.sharedFragments)
    store.sharedFragments = {};
  return store.sharedFragments;
}
function getSharedFragment(key) {
  if (!key)
    return "";
  return getSharedFragments()[key] || "";
}
function hasSharedFragment(key) {
  return getSharedFragment(key).trim() !== "";
}
function setSharedFragment(key, value) {
  if (!key)
    return;
  const bag = getSharedFragments();
  if (!value || value.trim() === "")
    delete bag[key];
  else
    bag[key] = value;
  saveSettingsDebounced();
}
function resolveSlot(slot, engine) {
  if (!slot || !slot.key)
    return { value: "", source: "builtin" };
  const fromEngine = engine && engine[slot.key];
  if (typeof fromEngine === "string" && fromEngine.trim() !== "") {
    return { value: fromEngine, source: "engine" };
  }
  const fromShared = getSharedFragment(slot.key);
  if (fromShared.trim() !== "") {
    return { value: fromShared, source: "shared" };
  }
  let builtin = "";
  try {
    builtin = (typeof slot.fallback === "function" ? slot.fallback(localProfile) : "") || "";
  } catch {
    builtin = "";
  }
  return { value: builtin, source: "builtin" };
}
function engineShadowsShared(slot, engine) {
  if (!slot || !slot.key || !engine)
    return false;
  if (slot.scope !== "shared")
    return false;
  const v = engine[slot.key];
  return typeof v === "string" && v.trim() !== "";
}

