// src/engine/chatText.js
function cleanAIOutput(text) {
  if (!text)
    return "";
  const re = new RegExp("(<disclaimer>.*?</disclaimer>)|(<guifan>.*?</guifan>)|(<danmu>.*?</danmu>)|(<options>.*?</options>)|```start|```end|<done>|`<done>`|(.*?</think(ing)?>(\\n)?)|(<think(ing)?>[\\s\\S]*?</think(ing)?>(\\n)?)", "gs");
  return text.replace(re, "").trim();
}
function meguminCleanChatHistoryText(text) {
  if (!text)
    return "";
  let cleaned = text;
  cleaned = cleaned.replace(/<img[^>]*?alt=["']KazumaInline["'][^>]*?>/gi, "");
  cleaned = cleaned.replace(/<div[^>]*?title=["']KazumaFail\|[^>]*?>.*?<\/div>/gi, "");
  cleaned = cleaned.replace(/<img\s+[^>]*\/>|<div class="kazuma-img-placeholder"[^>]*>[\s\S]*?<\/div>|<!-- kazuma-inline-start:[^>]*-->[\s\S]*?<!-- kazuma-inline-end:[^>]*-->/gi, "");
  cleaned = cleaned.replace(/<details[^>]*>\s*<summary[^>]*>.*?💭.*?<b[^>]*>NPC Inner Chatter<\/b\s*><\/summary\s*>\s*([\s\S]*?)\s*<\/details\s*>/gi, "");
  cleaned = cleaned.replace(/<details[^>]*>\s*<summary[^>]*>.*?📌.*?<b[^>]*>World State<\/b\s*><\/summary\s*>\s*([\s\S]*?)\s*<\/details\s*>/gi, "");
  cleaned = cleaned.replace(/<details[^>]*>\s*<summary[^>]*>.*?🆕.*?<b[^>]*>New NPC:.*?<\/b\s*><\/summary\s*>\s*([\s\S]*?)\s*<\/details\s*>/gi, "");
  cleaned = cleaned.replace(/<div style="border: 1px solid #444;[\s\S]*?<\/div\s*>/gi, "");
  cleaned = cleaned.replace(/<Story_Tracker[^>]*>[\s\S]*?<\/Story_Tracker\s*>/gi, "");
  cleaned = cleaned.replace(/<Story_Tracker[^>]*>[\s\S]*$/i, "");
  cleaned = cleaned.replace(/<Blocks\b[^>]*>[\s\S]*?<\/Blocks\s*>/gi, "");
  const blockTags = meguminAllBlockTags();
  blockTags.forEach((tag) => {
    cleaned = cleaned.replace(new RegExp(`<${tag}\\b[^>]*>[\\s\\S]*?<\\/${tag}\\s*>`, "gi"), "");
  });
  cleaned = cleaned.replace(/<Blocks\b[^>]*>[\s\S]*$/i, "");
  blockTags.forEach((tag) => {
    cleaned = cleaned.replace(new RegExp(`<${tag}\\b[^>]*>[\\s\\S]*$`, "i"), "");
  });
  const badStuffRegex = /(<disclaimer>.*?<\/disclaimer>)|(<guifan>.*?<\/guifan>)|(<danmu>.*?<\/danmu>)|(<options>.*?<\/options>)|```start|```end|<done>|`<done>`|(.*?<\/(?:ksc??|think(?:ing)?)>(\n)?)|(<(?:ksc??|think(?:ing)?)>[\s\S]*?<\/(?:ksc??|think(?:ing)?)>(\n)?)/gs;
  cleaned = cleaned.replace(badStuffRegex, "");
  cleaned = cleaned.replace(/<details[^>]*>[\s\S]*?<\/details\s*>/gi, "");
  cleaned = cleaned.replace(/<summary[^>]*>[\s\S]*?<\/summary\s*>/gi, "");
  cleaned = cleaned.replace(/<details[^>]*>[\s\S]*$/i, "");
  cleaned = cleaned.replace(/<summary[^>]*>[\s\S]*$/i, "");
  cleaned = cleaned.replace(/<[^>]*>?/gm, "");
  return cleaned.trim();
}
function getCleanedChatHistory() {
  const context = getContext();
  if (!context.chat || context.chat.length === 0)
    return "";
  const aiMessages = context.chat.filter((m) => !m.is_user && !m.is_system).slice(-50);
  const badStuffRegex = /(<disclaimer>.*?<\/disclaimer>)|(<guifan>.*?<\/guifan>)|(<danmu>.*?<\/danmu>)|(<options>.*?<\/options>)|```start|```end|<done>|`<done>`|(.*?<\/(?:ksc??|think(?:ing)?)>(\n)?)|(<(?:ksc??|think(?:ing)?)>[\s\S]*?<\/(?:ksc??|think(?:ing)?)>(\n)?)/gs;
  let cleanedMessages = aiMessages.map((m) => meguminCleanChatHistoryText(m.mes));
  cleanedMessages = cleanedMessages.filter((t) => t.length > 0);
  return cleanedMessages.join(`

`);
}
function getChatForStoryDirector() {
  const context = getContext();
  if (!context.chat || context.chat.length === 0)
    return "";
  const limit = localProfile?.storyPlan?.contextLimit !== undefined ? localProfile.storyPlan.contextLimit : 100;
  let msgs = context.chat.filter((m) => !m.is_system);
  if (limit > 0) {
    msgs = msgs.slice(-limit);
  }
  let cleanedMessages = msgs.map((m) => {
    const cleanText = meguminCleanChatHistoryText(m.mes);
    if (!cleanText)
      return null;
    return `${m.name}: ${cleanText}`;
  }).filter((t) => t !== null);
  return cleanedMessages.join(`

`);
}
function getChatForNpcScan() {
  const context = getContext();
  if (!context.chat || context.chat.length === 0)
    return "";
  const depth = localProfile?.npcBank?.scanDepth || 60;
  const msgs = context.chat.filter((m) => !m.is_system).slice(-depth);
  return msgs.map((m) => `${m.name}: ${meguminCleanChatHistoryText(m.mes)}`).join(`

`);
}

// src/features/blocks/chomusukeIndicator.js
function initChomusukeIndicator() {
  onChomusukeStatus((s) => {
    const busy = Boolean(s.running || s.waiting);
    document.body.classList.toggle("meg-chomu-busy", busy);
    if (busy)
      $(".meg-chomu").attr("title", `Chomusuke: ${chomusukeStatusText(s)}`);
  });
  setChomusukeStopHandler(() => {
    const n = stopChomusukeJobs();
    if (n)
      toastr.info(n === 1 ? "Chomusuke stopped its job." : `Chomusuke stopped its ${n} jobs.`, "Chomusuke", { timeOut: 3000 });
  });
}

// src/utils/download.js
function downloadJsonFile(filename, dataObj) {
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(dataObj, null, 2));
  const downloadAnchorNode = document.createElement("a");
  downloadAnchorNode.setAttribute("href", dataStr);
  downloadAnchorNode.setAttribute("download", filename);
  document.body.appendChild(downloadAnchorNode);
  downloadAnchorNode.click();
  downloadAnchorNode.remove();
}

// src/features/npc/pfp.js
async function npcGeneratePfp(npcName) {
  const s = localProfile.imageGen;
  if (!s || !s.enabled) {
    toastr.warning("Turn on Images in the Images tab first.");
    return null;
  }
  const npc = localProfile.npcBank.npcs.find((n) => n.name === npcName);
  if (!npc)
    return null;
  const pfpIdentity = meguminActiveDataIdentity();
  const npcText = npcBuildTextFromData(npc);
  let styleStr = s.promptStyle === "illustrious" ? "Use Danbooru-style tags separated by commas. Focus on anime art style." : s.promptStyle === "sdxl" ? "Use natural, descriptive prose and full sentences. Focus on photorealism." : "Use a comma-separated list of detailed keywords and visual descriptors.";
  let perspStr = "This is a CHARACTER PORTRAIT. Frame it as an upper-body/bust shot focused on the character's face and shoulders. Soft, flattering lighting. Clean or simple background. Capture their personality through expression and posture.";
  toastr.info(`Generating portrait prompt for ${npcName}...`, "NPC Bank");
  showKazumaProgress("AI is writing portrait prompt...");
  setActiveNpcPfpRequest({ npcName, npcText, styleStr, perspStr, extraStr: s.promptExtra || "None" });
  let promptText;
  try {
    let rawOutput = await generateQuietPrompt({ prompt: "___PS_NPC_PFP___" });
    promptText = rawOutput.replace(/<think>[\s\S]*?<\/think>/g, "").trim();
    const imgRegex = /<img[^>]*?prompt=(["']?)([\s\S]*?)(?:\1\s*\/?>|\1\s*>|\1\s+[a-zA-Z]+=| \/>|>|$)/i;
    const match = promptText.match(imgRegex);
    if (match)
      promptText = match[2];
  } catch (e) {
    console.error("NPC PFP prompt generation failed:", e);
    $("#kazuma_progress_overlay").hide();
    toastr.error("Failed to generate portrait prompt.");
    setActiveNpcPfpRequest(null);
    return null;
  } finally {
    setActiveNpcPfpRequest(null);
  }
  if (!promptText || promptText.length < 5) {
    $("#kazuma_progress_overlay").hide();
    toastr.error("AI returned an empty prompt.");
    return null;
  }
  console.log(`[Megumin-Suite] NPC PFP prompt for ${npcName}: ${promptText}`);
  $("#kazuma_progress_overlay").hide();
  const $content = $(`
        <div style="display:flex; flex-direction:column; gap:10px; font-family: 'Inter', sans-serif;">
            <div style="font-size: 0.85rem; color: var(--text-muted);">Review or modify the character portrait prompt before rendering.</div>
            <textarea class="ps-modern-input npc-preview-textarea" style="height: 150px; resize: vertical; font-family: monospace; font-size: 0.85rem; padding: 10px;">${promptText}</textarea>
        </div>
    `);
  let liveText = promptText;
  $content.find(".npc-preview-textarea").on("input", function() {
    liveText = $(this).val();
  });
  const popup = new Popup($content, POPUP_TYPE.CONFIRM, `Edit Portrait Prompt: ${npcName}`, { okButton: "Render Portrait", cancelButton: "Cancel", wide: true });
  const confirmed = await popup.show();
  if (!confirmed) {
    toastr.info("Portrait generation cancelled.");
    setActiveNpcPfpRequest(null);
    return null;
  }
  promptText = liveText.trim();
  if (!promptText) {
    toastr.warning("Prompt cannot be empty.");
    setActiveNpcPfpRequest(null);
    return null;
  }
  toastr.info("Drawing the portrait...", "NPC Bank");
  showKazumaProgress("Rendering NPC Portrait...");
  let dataUrl = null;
  try {
    dataUrl = imageSource() === "lumi" ? await pfpDrawLumi(promptText, s) : await pfpDrawComfy(promptText, s);
    if (!dataUrl)
      throw new Error("the image generator returned no image");
  } catch (e) {
    $("#kazuma_progress_overlay").hide();
    toastr.error("Portrait failed: " + (e && e.message || e), "NPC Bank");
    return null;
  }
  const compressed = await new Promise((r) => {
    const img = new Image;
    img.src = dataUrl;
    img.onload = () => {
      const cvs = document.createElement("canvas");
      cvs.width = img.width;
      cvs.height = img.height;
      cvs.getContext("2d").drawImage(img, 0, 0);
      r(cvs.toDataURL("image/jpeg", 0.85));
    };
    img.onerror = () => r(dataUrl);
  });
  if (meguminActiveDataIdentity() !== pfpIdentity) {
    console.debug(`[Megumin-Suite] NPC portrait declined: it was generated for "${pfpIdentity}" but "${meguminActiveDataIdentity()}" is active now.`);
    $("#kazuma_progress_overlay").hide();
    return null;
  }
  npc.pfp = compressed;
  saveProfileToMemory();
  $("#kazuma_progress_overlay").hide();
  toastr.success(`Portrait generated for ${npcName}!`);
  fireRefreshHook(REFRESH.NPC_LIST);
  return compressed;
}
async function pfpDrawLumi(promptText, s) {
  const list = await call("imagegen:connections") || [];
  const c = s.lumiConnectionId && list.find((x) => x.id === s.lumiConnectionId) || list.find((x) => x.is_default) || list[0] || null;
  const res = await call("imagegen:generate", {
    prompt: promptText,
    negativePrompt: s.customNegative || "",
    connectionId: c ? c.id : null,
    wantDataUrl: true
  }, { timeoutMs: 600000 });
  return res && res.dataUrl;
}
async function pfpDrawComfy(promptText, s) {
  if (!s.currentWorkflowName)
    throw new Error("pick a ComfyUI workflow on the Images tab's Generator page");
  const wfRes = await comfyFetch("/api/sd/comfy/workflow", { method: "POST", body: JSON.stringify({ file_name: s.currentWorkflowName }) });
  if (!wfRes.ok)
    throw new Error(`could not load ${s.currentWorkflowName}`);
  const raw = await wfRes.json();
  const workflow = typeof raw === "string" ? JSON.parse(raw) : raw;
  const seed = Math.floor(Math.random() * 1e9);
  const values = {
    "%prompt%": promptText,
    "%negative_prompt%": s.customNegative || "",
    "%seed%": seed,
    "%sampler%": s.selectedSampler || "euler",
    "%model%": s.selectedModel || "v1-5-pruned.ckpt",
    "%steps%": parseInt(s.steps) || 20,
    "%scale%": parseFloat(s.cfg) || 7,
    "%denoise%": parseFloat(s.denoise) || 1,
    "%clip_skip%": -Math.abs(parseInt(s.clipSkip)) || -1,
    "%lora1%": s.selectedLora || "None",
    "%lora2%": s.selectedLora2 || "None",
    "%lora3%": s.selectedLora3 || "None",
    "%lora4%": s.selectedLora4 || "None",
    "%lorawt1%": parseFloat(s.selectedLoraWt) || 1,
    "%lorawt2%": parseFloat(s.selectedLoraWt2) || 1,
    "%lorawt3%": parseFloat(s.selectedLoraWt3) || 1,
    "%lorawt4%": parseFloat(s.selectedLoraWt4) || 1,
    "%width%": 512,
    "%height%": 512
  };
  for (const nodeId in workflow) {
    const node = workflow[nodeId];
    if (!node.inputs)
      continue;
    for (const key in node.inputs) {
      if (Object.prototype.hasOwnProperty.call(values, node.inputs[key]))
        node.inputs[key] = values[node.inputs[key]];
    }
    if (node.class_type === "KSampler" && typeof node.inputs.seed === "number")
      node.inputs.seed = seed;
  }
  const base = s.comfyUrl;
  const q = await comfyFetch(`${base}/prompt`, { method: "POST", body: JSON.stringify({ prompt: workflow }) });
  if (!q.ok)
    throw new Error((await q.json()).error || "ComfyUI refused the workflow");
  const { prompt_id } = await q.json();
  for (let i = 0;i < 600; i++) {
    await new Promise((r) => setTimeout(r, 1000));
    const hRes = await comfyFetch(`${base}/history/${prompt_id}`);
    if (!hRes.ok)
      continue;
    const h = await hRes.json();
    if (!h[prompt_id])
      continue;
    let img = null;
    for (const nodeId in h[prompt_id].outputs) {
      const out = h[prompt_id].outputs[nodeId];
      if (out.images && out.images.length) {
        img = out.images[0];
        break;
      }
    }
    if (!img)
      return null;
    const view = await comfyFetch(`${base}/view?filename=${encodeURIComponent(img.filename)}&subfolder=${encodeURIComponent(img.subfolder || "")}&type=${encodeURIComponent(img.type || "output")}`);
    if (!view.ok)
      throw new Error("ComfyUI finished but the image could not be fetched");
    const blob = await view.blob();
    return await new Promise((r) => {
      const reader = new FileReader;
      reader.onloadend = () => r(reader.result);
      reader.readAsDataURL(blob);
    });
  }
  throw new Error("ComfyUI did not finish within 10 minutes");
}

// src/features/npc/ui.js
var escv = (v) => escapeHtmlAttr(v == null ? "" : v);
var SAFE_PFP = /^data:image\/(png|jpe?g|webp);base64,[A-Za-z0-9+/=]+$/;
var safePfp = (v) => typeof v === "string" && SAFE_PFP.test(v) ? v : "";
function npcCleanImported(raw) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw))
    return null;
  const out = {};
  for (const [k, v] of Object.entries(raw)) {
    if (k === "history" || k === "pfp" || k === "imageOnly" || k === "timestamp" || k === "messageIndex")
      continue;
    if (typeof v === "string")
      out[k] = v;
    else if (typeof v === "number" || typeof v === "boolean")
      out[k] = String(v);
  }
  if (!(out.name || "").trim())
    return null;
  out.pfp = safePfp(raw.pfp);
  out.imageOnly = raw.imageOnly === true;
  out.timestamp = Number.isFinite(raw.timestamp) ? raw.timestamp : Date.now();
  out.messageIndex = Number.isInteger(raw.messageIndex) && raw.messageIndex >= 0 ? raw.messageIndex : 0;
  out.history = Array.isArray(raw.history) ? raw.history.filter((e) => e && typeof e === "object" && !Array.isArray(e)) : [];
  return out;
}
